<?php

declare(strict_types=1);

namespace Koravik\Districts\Gather;

use Koravik\Platform\Database\Database;
use Koravik\Platform\Security\Security;
use RuntimeException;

final class GatherOperationsController
{
    public function __construct(private readonly Database $database) {}

    public function handle(string $method,string $path):bool
    {
        if($method==='GET'&&preg_match('#^/gather/events/([a-f0-9-]{36})/command$#',$path,$m)){$this->command($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/gather/events/([a-f0-9-]{36})/settings$#',$path,$m)){$this->settings($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/gather/events/([a-f0-9-]{36})/details$#',$path,$m)){$this->details($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/gather/events/([a-f0-9-]{36})/slots/([a-f0-9-]{36})$#',$path,$m)){$this->slot($m[1],$m[2]);return true;}
        if($method==='POST'&&preg_match('#^/gather/events/([a-f0-9-]{36})/slots/([a-f0-9-]{36})/delete$#',$path,$m)){$this->deleteSlot($m[1],$m[2]);return true;}
        if($method==='POST'&&preg_match('#^/gather/events/([a-f0-9-]{36})/slots/([a-f0-9-]{36})/assign$#',$path,$m)){$this->assignSlot($m[1],$m[2]);return true;}
        if($method==='POST'&&preg_match('#^/gather/events/([a-f0-9-]{36})/check-in$#',$path,$m)){$this->checkIn($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/gather/events/([a-f0-9-]{36})/check-in/correct$#',$path,$m)){$this->correct($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/gather/events/([a-f0-9-]{36})/announce$#',$path,$m)){$this->announce($m[1]);return true;}
        return false;
    }

    private function command(string $eventId):void
    {
        $account=Security::requireAccount();
        try{$event=(new GatherCommandService($this->database))->dashboard((string)$account['id'],$eventId);}
        catch(RuntimeException){http_response_code(404);echo $this->page('Event not found','<section class="empty-state"><h1>Event not found.</h1></section>');return;}

        $rows='';
        foreach($event['rsvps'] as $rsvp){
            $name=self::e((string)($rsvp['guest_name']?:'Koravik member'));
            $checked=(int)($rsvp['checked_in_party_count']??0);
            $dayOf=$checked>0
                ?'<p><strong>'.$checked.' checked in</strong></p><form method="post" action="/gather/events/'.self::e($eventId).'/check-in/correct"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><input type="hidden" name="rsvp_id" value="'.self::e((string)$rsvp['id']).'"><label>Correction note<input name="note" maxlength="500" required></label><button class="button secondary" type="submit">Void check-in</button></form>'
                :'<form method="post" action="/gather/events/'.self::e($eventId).'/check-in"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><input type="hidden" name="rsvp_id" value="'.self::e((string)$rsvp['id']).'"><label>Party arriving<input name="party_count" type="number" min="1" max="'.(int)$rsvp['party_size'].'" value="'.(int)$rsvp['party_size'].'"></label><button class="button secondary" type="submit">Check in</button></form>';
            $rows.='<tr><td>'.$name.'</td><td>'.self::e(ucfirst((string)$rsvp['response'])).'</td><td>'.(int)$rsvp['party_size'].'</td><td>'.$dayOf.'</td></tr>';
        }

        $mail='';
        foreach($event['mail'] as $delivery){
            $detail=$delivery['status']==='failed'&&$delivery['failure_reason']?' · '.self::e((string)$delivery['failure_reason']):'';
            $mail.='<li><strong>'.self::e((string)$delivery['subject']).'</strong><br>'.self::e((string)$delivery['recipient_email']).' · '.self::e((string)$delivery['status']).' · attempt '.(int)$delivery['attempts'].$detail.'</li>';
        }

        $history='';
        foreach($event['announcements'] as $announcement){
            $history.='<li><strong>'.self::e((string)$announcement['title']).'</strong> · '.self::e((string)$announcement['audience']).' · '.self::e((string)$announcement['urgency']).'<br>'.nl2br(self::e((string)$announcement['message'])).'</li>';
        }

        $rsvpOptions='';
        foreach($event['rsvps'] as $rsvp){$label=($rsvp['guest_name']?:$rsvp['guest_email']?:'Koravik member').' · '.ucfirst((string)$rsvp['response']);$rsvpOptions.='<option value="'.self::e((string)$rsvp['id']).'">'.self::e((string)$label).'</option>';}
        $slotOptions='';
        foreach($event['slots'] as $slot){$slotOptions.='<option value="'.self::e((string)$slot['id']).'">'.self::e((string)$slot['title']).'</option>';}
        $signupRows='';
        foreach($event['slots'] as $slot){
            $cat=(string)($slot['category_key']?:$slot['slot_type']);$type=(string)$slot['slot_type'];
            $typeOption=static fn(string $value,string $label):string=>'<option value="'.$value.'"'.($type===$value?' selected':'').'>'.$label.'</option>';
            $catOption=static fn(string $value,string $label):string=>'<option value="'.$value.'"'.($cat===$value?' selected':'').'>'.$label.'</option>';
            $signupRows.='<article class="surface gather-mod-slot-card"><form method="post" action="/gather/events/'.self::e($eventId).'/slots/'.self::e((string)$slot['id']).'" class="form-grid"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>Category<select name="category_key">'.$catOption('food','Food and potluck').$catOption('shift','Volunteer shifts').$catOption('equipment','Equipment and gear').$catOption('supplies','Supplies and materials').$catOption('setup','Setup crew').$catOption('cleanup','Cleanup crew').$catOption('transport','Transportation').$catOption('childcare','Childcare and care roles').$catOption('accessibility','Accessibility support').$catOption('other','Other needs').'</select></label><label>Type<select name="type">'.$typeOption('potluck','Food / potluck item').$typeOption('shift','Timed shift').$typeOption('item','Equipment or supply').$typeOption('task','Task or role').'</select></label><label>Title<input name="title" value="'.self::e((string)$slot['title']).'" required></label><label class="full">Description<textarea name="description" maxlength="500">'.self::e((string)($slot['description']??'')).'</textarea></label><label>Starts<input name="starts_at" type="datetime-local" value="'.self::e(str_replace(' ','T',(string)($slot['starts_at']??''))).'"></label><label>Ends<input name="ends_at" type="datetime-local" value="'.self::e(str_replace(' ','T',(string)($slot['ends_at']??''))).'"></label><label>Quantity needed<input name="quantity" type="number" min="1" value="'.(int)$slot['quantity_needed'].'"></label><label>Max quantity per claim<input name="max_quantity_per_commitment" type="number" min="1" value="'.self::e((string)($slot['max_quantity_per_commitment']??'')).'"></label><label><input type="checkbox" name="multiple_signups_allowed"'.((int)$slot['multiple_signups_allowed']?' checked':'').'> Allow multiple signups</label><label>Maximum signups per participant<input name="max_signups_per_participant" type="number" min="1" value="'.self::e((string)($slot['max_signups_per_participant']??'')).'"></label><label><input type="checkbox" name="waitlist_enabled"'.((int)$slot['waitlist_enabled']?' checked':'').'> Waitlist</label><p class="form-note full">People must RSVP “Yes” before claiming food, shifts, equipment, or other signup needs.</p><label><input type="checkbox" name="overlapping_shifts_allowed"'.((int)$slot['overlapping_shifts_allowed']?' checked':'').'> Allow overlapping shifts</label><button class="button" type="submit">Save signup</button></form><form method="post" action="/gather/events/'.self::e($eventId).'/slots/'.self::e((string)$slot['id']).'/assign" class="gather-inline-assign"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>Assign RSVP<select name="rsvp_id"><option value="">Choose participant</option>'.$rsvpOptions.'</select></label><label>Quantity<input name="quantity" type="number" min="1"'.($slot['max_quantity_per_commitment']?' max="'.(int)$slot['max_quantity_per_commitment'].'"':'').' value="1"></label><button class="button secondary" type="submit">Assign signup</button></form><form method="post" action="/gather/events/'.self::e($eventId).'/slots/'.self::e((string)$slot['id']).'/delete" onsubmit="return confirm(\'Delete this signup and its commitments?\')" class="gather-delete-form"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><button class="quiet-button" type="submit">Delete signup</button></form></article>';
        }
        $visibility=(string)$event['visibility'];
        $option=static fn(string $value,string $label):string=>'<option value="'.$value.'"'.($visibility===$value?' selected':'').'>'.$label.'</option>';
        $eventAccent=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($event['event_accent_color']??''))?(string)$event['event_accent_color']:'#D4A53A';
        $eventStyle=(string)($event['event_header_style']??'classic');
        $styleOption=static fn(string $value,string $label):string=>'<option value="'.$value.'"'.($eventStyle===$value?' selected':'').'>'.$label.'</option>';
        $brandStyle='style="--event-accent:'.self::e($eventAccent).'"';

        $body='<section class="page-heading gather-command-mission-control gather-event-header header-style-'.self::e($eventStyle).'" '.$brandStyle.'><div><p class="eyebrow">Gather command center · Host Mission Control</p><h1>'.self::e((string)$event['title']).'</h1><p>Run the event from one place: edit the event, set attendance rules, add food / shifts / equipment, manage signups, check people in, and message guests.</p></div><p class="local-actions"><a href="/gather/events/'.self::e($eventId).'">Open public event view</a><a href="#edit-event-details">Edit event details</a><a href="#add-signup-needs">Add food, shifts, equipment</a><a href="#manage-signups">Manage existing signups</a><a href="/gather/events/'.self::e($eventId).'/day-of">Day-of check-in</a><a href="/gather/events/'.self::e($eventId).'/closeout">Closeout</a></p></section>'
            .'<section class="surface gather-ops-presence-panel"><h2>What Gather owns</h2><p>Gather owns event truth: RSVP, signup, waitlist, attendance, walk-ins, announcements, mail delivery records, and follow-up drafts. Beacon may share the public doorway; Source Review may prepare next steps; neither takes over Gather records.</p></section>'
            .'<section class="grid"><article class="surface"><h2>Confirmed</h2><p class="metric">'.(int)$event['confirmed'].'</p></article><article class="surface"><h2>Waitlisted</h2><p class="metric">'.(int)$event['waitlisted'].'</p></article><article class="surface"><h2>Checked in</h2><p class="metric">'.(int)$event['checked_in'].'</p></article><article class="surface"><h2>Open signup units</h2><p class="metric">'.(int)$event['open_signup_units'].'</p></article></section>'
            .'<section class="gather-command-roadmap" aria-label="Organizer steps"><a href="#edit-event-details"><strong>1. Edit event details</strong><span>Name, time, venue, description</span></a><a href="#event-rules"><strong>2. Set attendance rules</strong><span>Capacity, guests, waitlist</span></a><a href="#add-signup-needs"><strong>3. Add signup needs</strong><span>Food, shifts, equipment, supplies</span></a><a href="#manage-signups"><strong>4. Manage people</strong><span>Edit, assign, delete, check in</span></a></section>'
            .'<section id="edit-event-details" class="surface gather-event-editor gather-command-step"><p class="eyebrow">Step 1 · Event basics and branding</p><h2>Edit the event details guests will see</h2><p class="helper-text">Use this when the title, date, location, public description, or event accent changes. Nothing else on this page changes until you press Save.</p><form method="post" action="/gather/events/'.self::e($eventId).'/details" class="form-grid"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>Event title<input name="title" maxlength="180" required value="'.self::e((string)$event['title']).'"></label><label>Start date and time<input name="starts_at" type="datetime-local" required value="'.self::e(str_replace(' ','T',(string)$event['starts_at'])).'"></label><label>End date and time <span class="optional">Optional</span><input name="ends_at" type="datetime-local" value="'.self::e(str_replace(' ','T',(string)($event['ends_at']??''))).'"></label><label>Venue or location<input name="venue" value="'.self::e((string)($event['venue']??'')).'" placeholder="Church hall, Room 204, online link, address"></label><label>Event accent color<input name="event_accent_color" type="color" value="'.self::e($eventAccent).'"></label><label>Event header style<select name="event_header_style">'.$styleOption('classic','Classic parchment').$styleOption('forest','Forest').$styleOption('gold','Warm gold').$styleOption('navy','Deep navy').$styleOption('custom','Use my accent strongly').'</select></label><label class="full">Description guests read<textarea name="description" placeholder="What should people know before they RSVP?">'.self::e((string)($event['description']??'')).'</textarea></label><button class="button" type="submit">Save event details and branding</button></form></section>'
            .'<section id="event-rules" class="surface gather-command-step"><p class="eyebrow">Step 2 · Attendance rules</p><h2>Set RSVP, guest, capacity, and waitlist rules</h2><p class="helper-text">These controls decide who can RSVP and how full-event limits behave. If you are unsure, the checked defaults are the friendliest starting point.</p><form method="post" action="/gather/events/'.self::e($eventId).'/settings" class="form-grid"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>Who can see this event?<select name="visibility">'.$option('unlisted','Anyone with link').$option('public','Public').$option('restricted','Restricted').'</select></label><label>Total event capacity <span class="optional">Blank means no limit</span><input name="capacity" type="number" min="1" value="'.self::e((string)($event['capacity']??'')).'"></label><label><input type="checkbox" name="guest_registration_enabled"'.((int)$event['guest_registration_enabled']?' checked':'').'> People can RSVP</label><label><input type="checkbox" name="additional_guests_enabled"'.((int)$event['additional_guests_enabled']?' checked':'').'> People can bring additional guests</label><label>Max additional guests per RSVP<input name="max_additional_guests" type="number" min="0" value="'.(int)$event['max_additional_guests'].'"></label><label><input type="checkbox" name="waitlist_enabled"'.((int)$event['waitlist_enabled']?' checked':'').'> Use a waitlist when full</label><label><input type="checkbox" name="automatic_waitlist_promotion"'.((int)$event['automatic_waitlist_promotion']?' checked':'').'> Automatically offer openings to waitlisted people</label><label>Max signup claims per participant <span class="optional">Optional</span><input name="max_signups_per_participant" type="number" min="1" value="'.self::e((string)($event['max_signups_per_participant']??'')).'"></label><label>Waitlist offer expires after minutes<input name="waitlist_offer_minutes" type="number" min="15" value="'.(int)$event['waitlist_offer_minutes'].'"></label><label>Organizer reply-to email<input name="organizer_reply_to_email" type="email" value="'.self::e((string)($event['organizer_reply_to_email']??'')).'"></label><button class="button" type="submit">Save attendance rules</button></form></section>'
            .'<section id="add-signup-needs" class="surface gather-signup-builder gather-command-step"><p class="eyebrow">Step 3 · Food, shifts, equipment, supplies</p><h2>Add something people can sign up for</h2><p class="helper-text">Pick what kind of help you need, give it a plain-language title, and say how many people or items are needed. Examples: “Bring salad,” “Greeter shift 5–6 PM,” “Two folding tables,” “Cleanup crew.” People must RSVP “Yes” before claiming any signup.</p><div class="gather-template-strip" aria-label="Common signup examples"><span>Food / potluck</span><span>Volunteer shift</span><span>Equipment</span><span>Supplies</span><span>Setup</span><span>Cleanup</span></div><form method="post" action="/gather/events/'.self::e($eventId).'/slots" class="form-grid"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>What kind of signup is this?<select name="category_key"><option value="food">Food and potluck</option><option value="shift">Volunteer shifts</option><option value="equipment">Equipment and gear</option><option value="supplies">Supplies and materials</option><option value="setup">Setup crew</option><option value="cleanup">Cleanup crew</option><option value="transport">Transportation</option><option value="childcare">Childcare and care roles</option><option value="accessibility">Accessibility support</option><option value="other">Other needs</option></select></label><label>How should Gather treat it?<select name="type"><option value="potluck">Food / potluck item</option><option value="shift">Timed shift</option><option value="item">Equipment or supply</option><option value="task">Task or role</option></select></label><label>Plain-language title<input name="title" required placeholder="Salad, Greeter 5 PM, folding table, extension cord"></label><label class="full">Instructions for the person signing up<textarea name="description" maxlength="500" placeholder="Dietary notes, where to report, item size, setup instructions, or anything they should know."></textarea></label><label>Starts <span class="optional">For shifts/tasks</span><input name="starts_at" type="datetime-local"></label><label>Ends <span class="optional">For shifts/tasks</span><input name="ends_at" type="datetime-local"></label><label>How many are needed?<input name="quantity" type="number" min="1" value="1"></label><label>Max one person can claim <span class="optional">Optional</span><input name="max_quantity_per_commitment" type="number" min="1"></label><label><input type="checkbox" name="multiple_signups_allowed" checked> Let more than one person claim this when quantity is above 1</label><label>Maximum signups per participant <span class="optional">Optional</span><input name="max_signups_per_participant" type="number" min="1"></label><label><input type="checkbox" name="waitlist_enabled" checked> Keep a waitlist if this fills</label><p class="form-note full">Attendance is required: if someone is not going, they cannot claim this need.</p><label><input type="checkbox" name="overlapping_shifts_allowed"> Allow overlapping shifts</label><button class="button" type="submit">Add this signup need</button></form></section>'
            .'<section id="manage-signups" class="gather-mod-signups"><div class="section-heading"><h2>Step 4 · Manage existing signups</h2><span>Edit, assign, or delete food, shifts, equipment, and other needs</span></div>'.($signupRows?:'<article class="empty-state"><h3>No signup needs yet.</h3><p>Use Step 3 above to add food, volunteer shifts, equipment, supplies, setup, cleanup, or any other need.</p></article>').'</section>'
            .'<section class="surface"><h2>Attendees and check-in</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>RSVP</th><th>Party</th><th>Day-of</th></tr></thead><tbody>'.($rows?:'<tr><td colspan="4">No RSVPs yet.</td></tr>').'</tbody></table></div></section>'
            .'<section class="grid"><article class="surface"><h2>Send an update</h2><form method="post" action="/gather/events/'.self::e($eventId).'/announce"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>Audience<select name="audience"><option value="all">Everyone with an RSVP</option><option value="confirmed">Confirmed attendees</option><option value="waitlisted">Waitlisted guests</option><option value="volunteers">All volunteer shifts</option>'.($slotOptions?'<option value="slot">One signup slot</option>':'').'</select></label>'.($slotOptions?'<label>Signup slot<select name="audience_reference"><option value="">Choose when targeting one slot</option>'.$slotOptions.'</select></label>':'').'<label>Title<input name="title" maxlength="180" required></label><label>Message<textarea name="message" required></textarea></label><label><input type="checkbox" name="urgent"> Urgent</label><label><input type="checkbox" name="email_enabled" checked> Email recipients</label><button class="button" type="submit">Save and send update</button></form></article><article class="surface"><h2>Recent updates</h2><ul>'.($history?:'<li>No updates yet.</li>').'</ul></article></section>'
            .'<section class="surface"><h2>Recent email delivery</h2><ul>'.($mail?:'<li>No event-linked mail yet.</li>').'</ul></section>';
        echo $this->page((string)$event['title'],$body);
    }

    private function settings(string $id):void{$this->csrf();$a=Security::requireAccount();try{(new GatherCommandService($this->database))->updateSettings((string)$a['id'],$id,$_POST);$_SESSION['flash']='Event settings updated.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/gather/events/'.$id.'/command');}
    private function details(string $id):void{$this->csrf();$a=Security::requireAccount();try{(new GatherCommandService($this->database))->updateDetails((string)$a['id'],$id,$_POST);$_SESSION['flash']='Event details updated.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/gather/events/'.$id.'/command');}
    private function slot(string $eventId,string $slotId):void{$this->csrf();$a=Security::requireAccount();try{(new GatherCommandService($this->database))->updateSlot((string)$a['id'],$eventId,$slotId,$_POST);$_SESSION['flash']='Signup updated.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/gather/events/'.$eventId.'/command');}
    private function deleteSlot(string $eventId,string $slotId):void{$this->csrf();$a=Security::requireAccount();try{(new GatherCommandService($this->database))->deleteSlot((string)$a['id'],$eventId,$slotId);$_SESSION['flash']='Signup deleted.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/gather/events/'.$eventId.'/command');}
    private function assignSlot(string $eventId,string $slotId):void{$this->csrf();$a=Security::requireAccount();try{$status=(new GatherCommandService($this->database))->assignSlot((string)$a['id'],$eventId,$slotId,(string)($_POST['rsvp_id']??''),(int)($_POST['quantity']??1));$_SESSION['flash']=$status==='waitlist'?'Participant assigned to the signup waitlist.':'Participant assigned to signup.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/gather/events/'.$eventId.'/command');}
    private function checkIn(string $id):void{$this->csrf();$a=Security::requireAccount();try{(new GatherDayOfService($this->database))->checkIn((string)$a['id'],$id,(string)($_POST['rsvp_id']??''),(int)($_POST['party_count']??1));$_SESSION['flash']='Check-in recorded.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/gather/events/'.$id.'/command');}
    private function correct(string $id):void{$this->csrf();$a=Security::requireAccount();try{(new GatherDayOfService($this->database))->correct((string)$a['id'],$id,(string)($_POST['rsvp_id']??''),(string)($_POST['note']??''));$_SESSION['flash']='Check-in voided with a correction record.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/gather/events/'.$id.'/command');}
    private function announce(string $id):void{$this->csrf();$a=Security::requireAccount();try{$count=(new GatherCommunicationService($this->database))->send((string)$a['id'],$id,$_POST);$_SESSION['flash']='Update saved; '.$count.' email delivery record(s) queued.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/gather/events/'.$id.'/command');}
    private function csrf():void{if(!Security::verifyCsrf((string)($_POST['csrf']??'')))throw new RuntimeException('Your session token expired.');}
    private function go(string $to):never{header('Location: '.$to,true,303);exit;}
    private function page(string $title,string $body):string{$flash='';if(isset($_SESSION['flash'])){$flash='<div class="notice">'.self::e((string)$_SESSION['flash']).'</div>';unset($_SESSION['flash']);}return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.self::e($title).' · Koravik</title><link rel="stylesheet" href="/assets/app.css"><link rel="stylesheet" href="/assets/journey.css"><link rel="stylesheet" href="/assets/gather.css"></head><body><main id="main" class="page gather-operations-presence">'.$flash.$body.'</main><footer>Koravik · Gather</footer></body></html>';}
    private static function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
}
